LL,NULL,NULL,'2024-07-04 09:20:51','2024-07-04 09:20:51'),(2654,'judge-event-evaluation-3281-1720048872',3281,111,6,11,2,2024,173,'451',NULL,7688,55,7844,2,'Open','8',100,83.00,-10,NULL,'Signature and date not on form',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-04 09:21:12','2024-07-04 09:21:12'),(2657,'judge-event-evaluation-3665-1720049053',3665,111,6,11,2,2024,7,'013',NULL,7648,55,7550,7,'Collection',NULL,100,93.00,-10,NULL,'Great work Adora! I think you did an excellent job with your short story. The characters, as well as the plot was well written. However, I felt that you could have elaborated more on Cassy\'s redemption. It would have added a clearer picture to the theme that you wanted to get across. Please also be mindful of how you write your characters conversing. Nonetheless, great job and I look forward to reading more of your work in the future!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-04 09:24:13','2024-07-04 09:24:13'),(2659,'judge-event-evaluation-3583-1720049133',3583,111,6,11,2,2024,204,'555',NULL,7730,55,7757,17,'Open',NULL,100,0.00,-10,NULL,'Piece not submitted.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-04 09:25:33','2024-07-04 09:25:33'),(2661,'judge-event-evaluation-3579-1720049237',3579,111,6,11,2,2024,202,'553',NULL,7730,55,7757,17,'Open',NULL,100,0.00,-10,NULL,'Piece not submitted.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-04 09:27:17','2024-07-04 09:27:17'),(2663,'judge-e