l the best for Convention 2024',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-05 12:16:08','2024-07-05 12:16:08'),(4054,'judge-event-evaluation-1757-1720145781',1757,115,6,11,2,2024,159,'400',NULL,7346,5804,7542,2,'Collection','7',100,70.00,-10,NULL,'Dear Lemeki.\r\n Thank you for your entry.\r\n\r\nVery impressive to see your portraiture but need to improve a lot. Try different techniques for the photo to stand out.\r\n\r\nRemember include your original photo.\r\n\r\nThank You and God Bless.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-05 12:16:21','2024-07-05 12:16:21'),(4055,'judge-event-evaluation-2604-1720145787',2604,149,6,11,2,2024,113,'302',NULL,7774,4678,7861,59,NULL,NULL,100,89.00,-10,NULL,'beautiful art work',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-05 12:16:27','2024-07-05 12:16:27'),(4056,'judge-event-evaluation-2701-1720145788',2701,111,6,11,2,2024,159,'400',NULL,7667,55,7844,2,'Collection','7',100,0.00,-10,NULL,'Breach....subject wearing sleeveless vest',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-05 12:16:28','2024-07-05 12:16:28'),(4058,'judge-event-evaluation-3518-1720145860',3518,111,6,11,2,2024,165,'406',NULL,7679,55,7839,2,NULL,NULL,100,0.00,-10,NULL,'Double Entry .I have judge the other one .',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2024-07-05 12:17:4