NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2025-06-24 08:27:30','2025-06-24 08:27:30'),(13377,'judge-event-evaluation-20248-1750717731',20248,346,16,11,3,2025,168,'412',NULL,7556,4208,8802,12,'Collection',NULL,100,77.00,NULL,NULL,'Thank you for creating this poster Yohan. It\'s a beautiful and uplifting poster. The Bible Verse you have chosen complements the image and creates a strong and meaningful message.\r\nOne small tip to make it stand out more the next time would be to use a higher-quality image as it would really enhance the overall impact.\r\nKeep up the great work!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2025-06-24 08:28:51','2025-06-24 08:28:51'),(13378,'judge-event-evaluation-21500-1750717757',21500,344,16,11,3,2025,137,'352',NULL,8858,55,7755,59,'Open',NULL,100,70.00,-10,NULL,'Thank you for your wood carving submission. \r\nGreat effort shown!\r\n I had to deduct some points bacause you need to do more work and focus on your carving especially the writting.\r\nmake sure that the words are bold and the message is clear and eye catching at the first glance.\r\nOverall, it looks good—keep up the hard work!\r\nSent',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2025-06-24 08:29:17','2025-06-24 08:29:17'),(13379,'judge-event-evaluation-21521-1750717766',21521,344,16,11,3,2025,160,'401',NULL,7718,55,8884,2,'Collection','8',100,81.00,-10,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2025-06-24 08:29:26','2025-06-24 08:29:26'),(13382,'judge-event-evaluation-21514-1750717878',21514,344,16,11,3,2025,160,'401',NULL,8860,55,8884,2,'Collection','8',100,