,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2026-06-23 09:33:38','2026-06-23 09:33:38'),(29743,'judge-event-evaluation-31298-1782171226',31298,642,24,24,7,2026,194,'506',NULL,7556,4208,9627,17,'Collection',NULL,100,59.00,-10,NULL,'Good job Yahan! This shows remarkable patience.\r\nThank you for your effort.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2026-06-23 09:33:46','2026-06-23 09:33:46'),(29744,'judge-event-evaluation-31221-1782171318',31221,642,24,24,7,2026,136,'351',NULL,8715,4208,7841,58,'Open',NULL,100,0.00,-10,NULL,'Project does not have the qualifying requirements for Wood Construction: having two or more different wood joints to hold item together.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2026-06-23 09:35:18','2026-06-26 09:22:57'),(29745,'judge-event-evaluation-31381-1782171326',31381,626,24,24,7,2026,191,'503',NULL,7359,5804,9613,17,NULL,NULL,100,66.00,-10,-2.00,'More effort required.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2026-06-23 09:35:26','2026-06-23 09:35:26'),(29749,'judge-event-evaluation-31327-1782171421',31327,642,24,24,7,2026,160,'401',NULL,9527,4208,9549,2,'Collection','8',100,87.00,-10,NULL,'A graceful and refined capture that celebrates the intricate beauty of orchids. The image feels peaceful, intentional, and reverent toward God’s creation. Beautifully captured, Joshua. Keep it up!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'2026-06-23 09:37:01','2026-06-23 0